SELECT COUNT(id)
FROM t_ai_task


        AND (biz_type LIKE concat('%', #{condition.keyword}, '%')
            OR task_type LIKE concat('%', #{condition.keyword}, '%')
            OR error_message LIKE concat('%', #{condition.keyword}, '%'))


        AND biz_type = #{condition.bizType}


        AND task_type = #{condition.taskType}


        AND status = #{condition.status}

SELECT id, biz_type, biz_id, task_type, status, retry_count, max_retry_count, error_message, model_name, prompt_version, started_at, finished_at, cost_time, create_time, update_time FROM t_ai_task
AND (biz_type LIKE concat('%', #{condition.keyword}, '%') OR task_type LIKE concat('%', #{condition.keyword}, '%') OR error_message LIKE concat('%', #{condition.keyword}, '%'))
AND biz_type = #{condition.bizType}
AND task_type = #{condition.taskType}
AND status = #{condition.status}
ORDER BY id DESC LIMIT #{limit}, #{size}
